func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/readyz", wrapper.GetReadiness)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/plans", wrapper.CreatePlan)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/plans/{planID}", wrapper.GetPlan)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/executions", wrapper.CreateExecution)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/publications", wrapper.CreatePublication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/publications/{customerID}/{target}", wrapper.GetPublication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/executions/{executionID}", wrapper.GetExecution)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/comparisons", wrapper.CreateComparison)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/comparisons/{comparisonID}", wrapper.GetComparison)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/policies/{customerID}/{target}", wrapper.GetPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/policies/{customerID}/{target}", wrapper.PutPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/corpora", wrapper.CreateCorpus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/corpora/{corpusID}", wrapper.GetCorpus)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/executions/{executionID}/reattempt", wrapper.ReattemptExecution)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/executions/{executionID}/checkpoints/{checkpointKey}", wrapper.GetExecutionCheckpoint)
	})

	return r
}

